#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;

    // Replace all "__" with "_"
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        s.replace(pos, 2, "_");
    }
    n = (int)s.length();

    int winCount = 0, maxSegmentLength = 0;
    int left = 0, right = 0;

    // Process the first segment if it starts with '('
    if (!s.empty() && s[left] == '(') {
        right = left;
        while (right < n && s[right] != ')') right++;
        if (right < n && s[right] == ')') {
            string inside = s.substr(left + 1, right - left - 1);
            if (inside.find('_') == string::npos && !inside.empty()) {
                winCount++;
            } else {
                int tokens = 1;
                for (char c : inside) {
                    if (c == '_') tokens++;
                }
                winCount += tokens;
            }
            left = right + 1;
        }
    }

    // Process other parentheses segments
    for (int index = 0; index < n; index++) {
        if (s[index] == '(') {
            int closeIdx = index;
            while (closeIdx < n && s[closeIdx] != ')') closeIdx++;
            if (closeIdx < n && s[closeIdx] == ')') {
                string inside = s.substr(index + 1, closeIdx - index - 1);
                if (inside.find('_') == string::npos && !inside.empty()) {
                    winCount++;
                } else {
                    int tokens = 1;
                    for (char c : inside) {
                        if (c == '_') tokens++;
                    }
                    winCount += tokens;
                }
                index = closeIdx;
            }
        }
    }

    // Replace all parentheses with underscores
    while (s.find('(') != string::npos || s.find(')') != string::npos) {
        size_t startPos = s.find('(');
        size_t endPos = s.find(')');
        if (startPos != string::npos && endPos != string::npos && startPos < endPos) {
            s.replace(startPos, endPos - startPos + 1, "_");
        } else {
            break;
        }
    }

    // Split the string by underscores and find max segment length
    stringstream ss(s);
    string segment;
    while (getline(ss, segment, '_')) {
        if ((int)segment.length() > maxSegmentLength) {
            maxSegmentLength = segment.length();
        }
    }

    cout << maxSegmentLength << " " << winCount << "\n";

    return 0;
}
